        $appContainer=[IO.Path]::GetDirectoryName([string]$envelope.app_backup_path)
        [void](Remove-CustomAppProductionPostApplyBoundedArtifactV010 -Path $appContainer -ExpectedRoot ([string]$envelope.app_backup_root) -ExpectedNamePattern '^[0-9a-fA-F]{32}$' -Label 'dual-id-resume-app-backup')
        Invoke-CustomAppProductionDualIdHousekeepingResumeValidationHookV010 -Checkpoint 'after-app-backup-cleanup' -Context ([pscustomobject]@{journal=$journal;resume=$envelope})
        [void](Remove-CustomAppProductionPostApplyBoundedArtifactV010 -Path ([string]$envelope.persistence_backup_path) -ExpectedRoot ([string]$envelope.persistence_backup_root) -ExpectedNamePattern '^txn-\d{8}-\d{6}-[0-9a-fA-F]{8}$' -Label 'dual-id-resume-persistence-backup')
        Invoke-CustomAppProductionDualIdHousekeepingResumeValidationHookV010 -Checkpoint 'after-persistence-backup-cleanup' -Context ([pscustomobject]@{journal=$journal;resume=$envelope})
    }catch{return & $deny ('dual-id-housekeeping-bounded-cleanup-interrupted:'+[string]$_.Exception.Message) $true $true}
    $post=Resolve-CustomAppProductionRecoveryHousekeepingResumeGateV010 -AllowedRoot $AllowedRoot -StoreDirectory $JournalStoreDirectory -ExpectedTransactionId ([string]$identity.journal_transaction_id) -LocalAppDataRoot $LocalAppDataRoot -AppDataRoot $AppDataRoot -Now $Now
    if($null-eq$post-or-not[bool]$post.ok){return & $deny ('dual-id-housekeeping-postcleanup-gate-denied:'+[string]$post.reason) $true $true}
    foreach($f in @('stage_cleanup_status','app_backup_cleanup_status','persistence_backup_cleanup_status')){if([string]$post.decision.$f-cne'already-absent'){return & $deny ('dual-id-housekeeping-postcleanup-artifact-still-present-'+$f) $true $true}}
    $ev=Read-CustomAppProductionRecoveryEvidenceV010 -AllowedRoot $AllowedRoot -StoreDirectory $JournalStoreDirectory -ExpectedTransactionId ([string]$identity.journal_transaction_id);if($null-eq$ev-or-not[bool]$ev.ok-or([string]$ev.evidence_fingerprint).Trim().ToLowerInvariant()-cne([string]$envelope.evidence_fingerprint).Trim().ToLowerInvariant()){return & $deny 'dual-id-housekeeping-recovery-evidence-drift' $true $true}
    $current=Read-CustomAppProductionCrashJournalV010 -AllowedRoot $AllowedRoot -StoreDirectory $JournalStoreDirectory;if($null-eq$current-or-not[bool]$current.ok-or[string]$current.entry.phase-cne'cleanup-starting'-or([string]$current.transaction_id).Trim().ToLowerInvariant()-cne([string]$identity.journal_transaction_id)){return & $deny 'dual-id-housekeeping-journal-drift-before-commit' $true $true}
    $result=[pscustomobject]@{schema=1;managed_by=$CustomAppProductionDualIdHousekeepingResumeExecutorManagedBy;status='dual-id-housekeeping-resume-committed-clean';name=([string]$identity.precommit.name).Trim().ToLowerInvariant();permit_transaction_id=[string]$identity.permit_transaction_id;journal_transaction_id=[string]$identity.journal_transaction_id;precommit_fingerprint=[string]$identity.precommit_fingerprint;bridge_fingerprint=[string]$identity.bridge_fingerprint;resume_fingerprint=([string]$envelope.resume_fingerprint).Trim().ToLowerInvariant();evidence_fingerprint=([string]$envelope.evidence_fingerprint).Trim().ToLowerInvariant();finalization_fingerprint=$finalFp;apply_evidence_fingerprint=$applyFp;live_runtime_tree_sha256=([string]$post.decision.live_runtime_tree_sha256).Trim().ToLowerInvariant();persistence_fingerprint=([string]$post.decision.persistence_fingerprint).Trim().ToLowerInvariant();stage_cleanup_status='already-absent';app_backup_cleanup_status='already-absent';persistence_backup_cleanup_status='already-absent';cleanup_starting_revision=[int64]$current.revision;committed_clean_revision=[int64]($current.revision+1);resume_envelope_preexisted=[bool]$preexisted;resume_envelope_persisted_before_cleanup=$true;transaction_id_namespaces_distinct=$true;spicetify_apply_executed=$false;recovery_evidence_retained=$true;requires_new_permit_for_future_update=$true;result_is_authority=$false;cleanup_authorized=$false;execution_authorized=$false;production_execution_authorized=$false;production_mutation_authorized=$false;cleanup_fingerprint=$null}
    $result.cleanup_fingerprint=Get-CustomAppProductionDualIdHousekeepingResumeSha256V010(Get-CustomAppProductionDualIdHousekeepingResumeResultMaterialV010 $result);$rc=Test-CustomAppProductionDualIdHousekeepingResumeResultV010 $result;if($null-eq$rc-or-not[bool]$rc.ok){return & $deny ('dual-id-housekeeping-result-self-check-denied:'+[string]$rc.reason) $true $true}
    try{Invoke-CustomAppProductionDualIdHousekeepingResumeValidationHookV010 -Checkpoint 'before-committed-clean' -Context ([pscustomobject]@{journal=$current;result=$result})}catch{return & $deny ('dual-id-housekeeping-simulated-crash-before-committed-clean:'+[string]$_.Exception.Message) $true $true}
    $commit=Append-CustomAppProductionCrashJournalPhaseV010 -AllowedRoot $AllowedRoot -StoreDirectory $JournalStoreDirectory -ExpectedRevision ([int64]$current.revision) -ExpectedEntrySha256 ([string]$current.entry.entry_sha256) -Phase 'committed-clean' -FinalizationFingerprint $finalFp -ApplyResultFingerprint $applyFp -CleanupResultFingerprint ([string]$result.cleanup_fingerprint) -Now (Get-CustomAppProductionDualIdHousekeepingResumeAppendTimeV010 -JournalEntry $current.entry -Now $Now)
    if($null-eq$commit-or-not[bool]$commit.ok-or-not[bool]$commit.persisted-or-not[bool]$commit.read_after_write_verified){return & $deny ('dual-id-housekeeping-committed-clean-append-denied:'+[string]$commit.reason) $true $true}
    $final=Read-CustomAppProductionCrashJournalV010 -AllowedRoot $AllowedRoot -StoreDirectory $JournalStoreDirectory;if($null-eq$final-or-not[bool]$final.ok-or[string]$final.entry.phase-cne'committed-clean'-or([string]$final.entry.finalization_fingerprint).Trim().ToLowerInvariant()-cne$finalFp-or([string]$final.entry.apply_result_fingerprint).Trim().ToLowerInvariant()-cne$applyFp-or([string]$final.entry.cleanup_result_fingerprint).Trim().ToLowerInvariant()-cne([string]$result.cleanup_fingerprint).Trim().ToLowerInvariant()){return & $deny 'dual-id-housekeeping-committed-clean-readback-denied' $true $true}
    return [pscustomobject]@{ok=$true;reason='dual-id-housekeeping-resume-committed-clean-without-reapply';result=$result;resume_envelope_persisted=$true;cleanup_starting_persisted=$true;committed_clean_persisted=$true;spicetify_apply_executed=$false;result_is_authority=$false;cleanup_authorized=$false;execution_authorized=$false;production_execution_authorized=$false;production_mutation_authorized=$false}
}
